#include TEST_INCLUDE
#include <cassert>
#include <limits>
bool near(double a,double b){return std::abs(a-b)<=2e-11*std::max(1.,std::max(std::abs(a),std::abs(b)));}
SystemState fixture(int k,int p){SystemState s{};s.num_partitions=p;s.memory_limit=100000;s.read_bandwidth=100;s.write_bandwidth=50;for(int op=0;op<k;++op){OperatorState o{};o.op_id=op;o.phase=Phase::PROBE;for(int j=0;j<p;++j){PartitionState x{};x.partition_id=j;x.data_size=100;x.in_memory=true;o.partitions.push_back(x);s.memory_used+=100;}s.operators.push_back(o);}return s;}
void check(MySpillScheduler&x,SystemState&s,const std::vector<double>&f,const std::vector<double>&c){int k=s.operators.size(),p=s.num_partitions;x.probability_cache_valid_=false;x.ensureProbabilities(s);double ft=0;for(double z:f)ft+=z;double total=0;for(int o=0;o<k;++o){double marginal=0,sm=0;for(int j=0;j<p;++j)sm+=c[o*p+j];assert(near(x.fast_operator_[o].mass,f[o]));assert(near(x.sharing_[o].mass,sm));for(int j=0;j<p;++j){int id=o*p+j;x.ensureProbability(id);double num=(1-x.sharing_[o].share)*c[id]+x.sharing_[o].share*sm/p+64./(k*p);double expected=(f[o]+64./k)/(ft+64)*num/(sm+64./k);assert(near(x.hier_probability_[id],expected)&&x.hier_probability_[id]>=0&&std::isfinite(x.hier_probability_[id]));marginal+=x.hier_probability_[id];}assert(near(marginal,(f[o]+64./k)/(ft+64)));total+=marginal;}assert(near(total,1));}
int main(){
 for(int k:{1,3})for(int p:{1,4}){auto s=fixture(k,p);MySpillScheduler x;x.update(s);std::vector<double>f(k),c(k*p);check(x,s,f,c);int last=0;for(int t=1;t<=150;++t){int q=last+1+(t%9==0?500:0),o=(t/7)%k,j=(t*t)%p;double ff=std::exp(-.693147180559945309417232121458176568*(q-last)/R81_FAST_HALF),fs=std::exp(-.693147180559945309417232121458176568*(q-last)/2048.);for(auto&z:f)z*=ff;for(auto&z:c)z*=fs;f[o]+=1;c[o*p+j]+=1;x.sampleNext(o,j,q);auto old=x.fast_operator_[o];x.sampleNext(o,j,q);assert(x.fast_operator_[o].mass==old.mass&&x.fast_operator_[o].last==old.last);s.hit_count=q;check(x,s,f,c);last=q;}int gap=10000000;s.hit_count+=gap;double ff=std::exp(-.693147180559945309417232121458176568*gap/R81_FAST_HALF),fs=std::exp(-.693147180559945309417232121458176568*gap/2048.);for(auto&z:f)z*=ff;for(auto&z:c)z*=fs;check(x,s,f,c);x.probability_epoch_=std::numeric_limits<uint64_t>::max();check(x,s,f,c);assert(x.probability_epoch_==1);}
 // A current miss is never a fast sample; next can advance to q+1, then miss q cannot rewind.
 {auto s=fixture(2,2);MySpillScheduler x;x.update(s);s.miss_count=10;x.update(s,0,0);for(auto&f:x.fast_operator_)assert(f.mass==0);s.next_op.type="PROBE";s.next_op.op_id=1;s.next_op.key=1;x.update(s,0,0);assert(x.fast_operator_[1].mass==1&&x.fast_operator_[1].last==11);x.update(s,1,0);assert(x.fast_operator_[1].mass==1&&x.fast_operator_[1].last==11);x.ensureProbabilities(s);assert(x.probability_clock_==11);}
 // Same observed stream means slow conditional and H are independent of the fast timescale.
 {auto s=fixture(2,3);MySpillScheduler x;x.update(s);for(int q=1;q<=3000;++q)x.sampleNext((q/173)%2,q%3,q);s.hit_count=3000;x.ensureProbabilities(s);auto slow=x.sharing_;std::vector<double>conditional(6);for(int id=0;id<6;++id){x.ensureProbability(id);double marginal=(x.fast_operator_[id/3].mass+32)/(x.fast_probability_total_+64);conditional[id]=x.hier_probability_[id]/marginal;}x.fast_operator_[0].mass*=3;x.probability_cache_valid_=false;x.ensureProbabilities(s);for(int id=0;id<6;++id){x.ensureProbability(id);double marginal=(x.fast_operator_[id/3].mass+32)/(x.fast_probability_total_+64);assert(near(conditional[id],x.hier_probability_[id]/marginal));}for(int o=0;o<2;++o)assert(x.sharing_[o].mass==slow[o].mass&&x.sharing_[o].share==slow[o].share&&x.sharing_[o].squares==slow[o].squares);}
 // Rapid alternating operator windows: compare exact oracle, without assuming improvement.
 {auto s=fixture(2,2);MySpillScheduler x;x.update(s);std::vector<double>f(2),c(4);for(int q=1;q<=3000;++q){for(auto&z:f)z*=std::exp(-.693147180559945309417232121458176568/R81_FAST_HALF);for(auto&z:c)z*=std::exp(-.693147180559945309417232121458176568/2048.);int o=(q/64)%2,p=q%2;f[o]++;c[o*2+p]++;x.sampleNext(o,p,q);}s.hit_count=3000;check(x,s,f,c);}
 std::cout<<"direct oracle, conditional independence, clocks, duplicates, empty/K1/P1/longgap/epoch PASS\n";
}
